style.css:
@-moz-document domain("instagram.com") {
/* 1. Eliminar límites artificiales de ancho del layout raíz */
  main,
  main[role="main"],
  div[role="main"],
  section._a99- {
    max-width: 100% !important;
    width: 100% !important;
    display: flex !important;
    justify-content: center !important;
  }

  /* 2. Contenedor del feed y sidebar lateral */
  main > div,
  main section > div {
    max-width: 1600px !important;
    width: 100% !important;
    display: flex !important;
    justify-content: center !important;
    gap: 40px !important;
  }

  /* 3. Columna del Feed principal */
  div[style*="max-width: 630px"],
  div[style*="max-width: 600px"],
  section > div > div > div:first-child {
    max-width: 780px !important;
    width: 100% !important;
  }

  /* 4. Ajuste de imágenes y videos en posts para evitar overflow vertical */
  article {
    max-width: 780px !important;
    width: 100% !important;
    margin-left: auto !important;
    margin-right: auto !important;
  }

  article div[role="button"] img,
  article video {
    max-height: 80vh !important;
    object-fit: contain !important;
  }

  /* 5. Historias (Stories carousel superior) */
  div[role="menu"] {
    max-width: 100% !important;
    justify-content: center !important;
  }

  /* 6. Barra lateral de navegación fija a la izquierda */
  div[role="navigation"] {
    z-index: 50 !important;
  }
}
